SELECT COUNT(*)
FROM course
WHERE day_of_week = #{dayOfWeek}
  AND place = #{place}
  AND time = #{time}

SELECT COUNT(*)
FROM course
WHERE day_of_week = #{dayOfWeek}
  AND place = #{place}
  AND time = #{time}
  AND id != #{id}

SELECT COUNT(*)
FROM course
WHERE professor_id = #{professorId}
  AND day_of_week = #{dayOfWeek}
  AND time = #{time}

SELECT COUNT(*)
FROM course
WHERE professor_id = #{professorId}
  AND day_of_week = #{dayOfWeek}
  AND time = #{time}
  AND id != #{id}

