UPDATE course
capacity = #{dto.capacity}, day_of_week = #{dto.dayOfWeek}, place = #{dto.place}, time = #{dto.time},
WHERE id = #{id}

UPDATE course
SET status = #{status}
WHERE id = #{courseId}

UPDATE course
SET num_of_student = num_of_student + #{change}
WHERE id = #{courseId}

UPDATE course
SET num_of_student = 0
WHERE id = #{courseId}

UPDATE course
SET status = 'CLOSE'
WHERE id = #{id}
